package david.manager;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import org.json.*;import org.jf.smali.*;
public class VideoFeaturesSmokeTest {
 static int checks;static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);checks++;System.out.println("PASS "+name);}
 static byte[]utf(String s){return s.getBytes(StandardCharsets.UTF_8);}static String text(File f)throws Exception{return new String(FileOps.read(f,1000000),StandardCharsets.UTF_8);}
 static JSONObject args(File src,File out,String name,String format,String password,long split)throws Exception{return new JSONObject().put("paths",new JSONArray().put(src.getPath())).put("destination",out.getPath()).put("name",name).put("format",format).put("level","normal").put("password",password).put("splitBytes",split);}
 public static void main(String[]args)throws Exception{
  File root=new File(args[0],"video-features");root.mkdirs();File source=new File(root,"data.txt");byte[]bytes=new byte[180003];new Random(123).nextBytes(bytes);FileOps.writeAtomic(source,bytes,false);
  for(String format:ArchiveTools.FORMATS){String ext=format.equals("gzip")?"gz":format;File archive=new File(root,"sample."+ext);JSONObject result=ArchiveTools.create(args(source,root,archive.getName(),format,"",0));File dest=new File(root,"unpacked-"+format);ArchiveTools.extract(archive,dest,"");File actual=new File(dest,format.equals("gzip")?"sample":"data.txt");check(Arrays.equals(bytes,FileOps.read(actual,1000000)),format+" compression/extraction round trip");check(result.getJSONArray("outputs").length()==1,"output manifest for "+format);}
  for(String format:Arrays.asList("zip","7z")){File archive=new File(root,"locked."+format);ArchiveTools.create(args(source,root,archive.getName(),format,"correct",0));File dest=new File(root,"locked-"+format);boolean rejected=false;try{ArchiveTools.extract(archive,dest,"wrong");}catch(Exception e){rejected=true;}check(rejected&&!dest.exists(),format+" wrong password rolls extraction back");ArchiveTools.extract(archive,dest,"correct");check(Arrays.equals(bytes,FileOps.read(new File(dest,"data.txt"),1000000)),format+" AES password round trip");}
  for(String format:Arrays.asList("zip","7z","tar.gz")){String name="split."+format;JSONObject r=ArchiveTools.create(args(source,root,name,format,"",65537));check(r.getJSONArray("outputs").length()>1,format+" split volumes produced");File input=new File(root,name+(format.equals("zip")?"":".001")),dest=new File(root,"split-out-"+format);ArchiveTools.extract(input,dest,"");check(Arrays.equals(bytes,FileOps.read(new File(dest,"data.txt"),1000000)),format+" split archive extraction");}
  File folder=new File(root,"folder");folder.mkdir();FileOps.writeAtomic(new File(folder,"one.txt"),utf("one"),false);new File(folder,"empty").mkdir();File dirzip=new File(root,"folder.zip");ArchiveTools.create(args(folder,root,dirzip.getName(),"zip","",0));File dirout=new File(root,"folder-out");ArchiveTools.extract(dirzip,dirout,"");check(text(new File(dirout,"folder/one.txt")).equals("one")&&new File(dirout,"folder/empty").isDirectory(),"archive preserves nested files and empty directories");
  boolean fail=false;try{ArchiveTools.create(args(folder,folder,"recursive.zip","zip","",0));}catch(Exception e){fail=true;}check(fail&&!new File(folder,"recursive.zip").exists(),"recursive archive output rejected");
  fail=false;try{ArchiveTools.create(args(source,root,"sample.zip","zip","",0));}catch(Exception e){fail=true;}check(fail&&Arrays.equals(bytes,FileOps.read(source,1000000)),"collision preserves source and existing archive");
  File original=new File(root,"restore.txt");FileOps.writeAtomic(original,utf("new"),false);File backup=new File(original+".bak");FileOps.writeAtomic(backup,utf("old"),false);FileOps.restoreBackup(backup);check(text(original).equals("old")&&text(backup).equals("new"),"Restore swaps original and .bak");FileOps.restoreBackup(backup);check(text(original).equals("new")&&text(backup).equals("old"),"Restore is reversible");
  File x=new File(root,"x.txt"),y=new File(root,"y.txt");FileOps.writeAtomic(x,utf("x"),false);FileOps.writeAtomic(y,utf("y"),false);BatchFiles.rename(new JSONArray().put(new JSONObject().put("path",x.getPath()).put("name","y.txt")).put(new JSONObject().put("path",y.getPath()).put("name","x.txt")));check(text(x).equals("y")&&text(y).equals("x"),"batch rename supports swaps without collisions");
  File transfer=new File(root,"transfer");transfer.mkdir();BatchFiles.transfer(Arrays.asList(x,y),Arrays.asList("x.txt","y.txt"),transfer,false);check(x.exists()&&y.exists()&&text(new File(transfer,"x.txt")).equals("y"),"batch copy publishes all files and preserves sources");
  fail=false;try{BatchFiles.transfer(Arrays.asList(x,y),Arrays.asList("x.txt","y.txt"),transfer,true);}catch(Exception e){fail=true;}check(fail&&x.exists()&&y.exists(),"batch move collision rejected before deleting any source");
  File dexDir=new File(root,"smali");dexDir.mkdir();String base=".class public Ldemo/Base;\n.super Ljava/lang/Object;\n.field public value:I\n.method public call()V\n .registers 1\n return-void\n.end method\n";String child=".class public Ldemo/Child;\n.super Ldemo/Base;\n.method public call()V\n .registers 2\n iget v0, p0, Ldemo/Base;->value:I\n invoke-super {p0}, Ldemo/Base;->call()V\n const-string v0, \"Ldemo/Unrelated;\"\n return-void\n.end method\n";
  FileOps.writeAtomic(new File(dexDir,"Base.smali"),utf(base),false);FileOps.writeAtomic(new File(dexDir,"Child.smali"),utf(child),false);File dex=new File(root,"query.dex");SmaliOptions options=new SmaliOptions();options.apiLevel=28;options.jobs=1;options.outputDexFile=dex.getPath();if(!Smali.assemble(options,dexDir.getPath()))throw new AssertionError("fixture");DexEngine engine=new DexEngine(new File(root,"sessions"));engine.open(dex,new JSONArray().put("query.dex"));
  JSONObject q=new JSONObject().put("op","usages").put("kind","field").put("owner","Ldemo/Base;").put("signature","Ldemo/Base;->value:I");check(engine.query(q).getJSONArray("rows").length()==1,"DEX field uses follow real instructions");q.put("kind","method").put("signature","Ldemo/Base;->call()V");check(engine.query(q).getJSONArray("rows").length()==1,"DEX method calls");q.put("op","overrides");check(engine.query(q).getJSONArray("rows").length()==1,"DEX overriding method lookup");q.put("op","subclasses").put("kind","class").put("signature","Ldemo/Base;");check(engine.query(q).getJSONArray("rows").length()==1,"DEX subclass lookup");q.put("op","usages").put("owner","Ldemo/Unrelated;").put("signature","Ldemo/Unrelated;");check(engine.query(q).getJSONArray("rows").length()==0,"descriptor-shaped string is not a type use");
  File container=new File(root,"commit.apk");try(java.util.zip.ZipOutputStream z=new java.util.zip.ZipOutputStream(new FileOutputStream(container))){z.putNextEntry(new java.util.zip.ZipEntry("classes.dex"));z.write(FileOps.read(dex,1000000));z.closeEntry();}DexEngine apkEngine=new DexEngine(new File(root,"apk-session"));apkEngine.open(container,new JSONArray().put("classes.dex"));String beforeApk=FileOps.sha256(container);String apkCode=apkEngine.code("Ldemo/Child;","smali","auto").getString("text");apkEngine.save("Ldemo/Child;",apkCode.replace("Ldemo/Unrelated;","APK change"));JSONObject committedApk=apkEngine.commit();check(FileOps.sha256(new File(committedApk.getString("backup"))).equals(beforeApk)&&committedApk.getBoolean("needsSigning"),"APK save-and-exit preserves original backup and marks signing requirement");DexEngine reopened=new DexEngine(new File(root,"reopened-apk"));reopened.open(container,new JSONArray().put("classes.dex"));check(reopened.code("Ldemo/Child;","smali","auto").getString("text").contains("APK change"),"APK save-and-exit changes survive reopening");apkEngine.close();reopened.close();
  String code=engine.code("Ldemo/Child;","smali","auto").getString("text");engine.save("Ldemo/Child;",code.replace("Ldemo/Unrelated;","changed"));String hash=FileOps.sha256(dex);JSONObject committed=engine.commit();check(new File(committed.getString("backup")).isFile()&&FileOps.sha256(new File(committed.getString("backup"))).equals(hash)&&!FileOps.sha256(dex).equals(hash),"DEX commit replaces source and preserves exact backup");
  engine.open(dex,new JSONArray().put("query.dex"));FileOps.writeAtomic(dex,utf("external change"),false);fail=false;try{engine.commit();}catch(Exception e){fail=true;}check(fail&&text(dex).equals("external change"),"DEX commit refuses externally changed source");engine.close();
  JSONObject diff=CompareTools.compare(new File(root,"sample.zip"),dirzip,"apk");check(diff.getInt("added")>0&&diff.getInt("removed")>0,"archive comparison reports entry differences");
  System.out.println("ALL "+checks+" VIDEO FEATURE CHECKS PASSED");
 }
}
